text:
{
  "characters": [
    {
      "id": "mina",
      "want": "灯りを絶やさず、港町の人々と父を守りたい。",
      "need": "務めを守ることと、兄の選択の真実を受け継ぐことは両立できると認め、自分の判断で灯りのあり方を選ぶ必要がある。",
      "fear": "自分の判断で灯りを消し、霧に港町を呑ませること。",
      "wound": "兄ヨハンは三年前の嵐の夜に死んだと聞かされ、その理由も分からぬまま、灯寮の記録では臆病者として扱われている。",
      "secret": "兄の死をめぐる答えを求める気持ちを、務めへの忠実さの陰に隠している。",
      "principle": "人々の命を守る責任を優先するが、責任の名のもとに真実を伏せることには、やがて抗う。",
      "self_view": "父の教えを継ぎ、灯りを守ることで皆を守る者。",
      "others_view": [
        "ロデリクから見れば、危険を知らずに鍵と務めを背負おうとする娘。",
        "セスから見れば、託された潮札を真剣に読み解こうとする灯守の娘。",
        "ヒルダから見れば、記録の嘘を知った後に選択を引き受けられる後継者。"
      ],
      "predictions": [
        {
          "situation": "嵐の夜、鍵を手放せば灯りを消せると考えたとき。",
          "choice": "港町を霧から守る務めを優先し、鍵を手放さない。"
        },
        {
          "situation": "潮鏡に、王都の棚にある石膏の右手と鍵が映ったとき。",
          "choice": "兄の手形に鍵がある事実を確かめ、灯りを保つ時間を計算したうえで王都へ向かう。"
        },
        {
          "situation": "通日九日、半灯の手順を得て、灯りを守るか兄の鍵を追うか迫られたとき。",
          "choice": "半灯の刻みを選び、鍵を回収して灯りも継ぐ。"
        }
      ],
      "speech": {
        "sample": "油の残りは数えたわ。だからこそ、知らないまま従うのではなく、何を守るための灯りなのか確かめたいの。",
        "vocab": [
          "油",
          "務め",
          "確かめる",
          "港町"
        ],
        "avoid": [
          "選ばれし者",
          "運命だから",
          "どうでもいい"
        ]
      },
      "arc": {
        "endpoint": "教えられた手順に従う娘から、真実を知ったうえで半灯を選び、灯りと兄の記憶の双方を守る灯守へ。",
        "changed": [
          "灯りを守ることは全灯を保つことだという考えを改め、半灯を自分の判断で選ぶ。",
          "兄を臆病者とする灯寮の記録を受け入れず、ヨハンの選択の真実を受け継ぐ。"
        ],
        "unchanged": [
          "港町の人々を危険にさらさないよう、油と残り日数を見極める。",
          "鍵を失えば灯台の務めが立ちゆかなくなるという責任感。"
        ]
      },
      "bans": [
        "鍵の複製や代替品を作ろうとする。",
        "油の期限や移動日数を無視した計画を立てる。",
        "兄の死を理由なく忘れたり、灯りへの責任を投げ出したりする。"
      ]
    },
    {
      "id": "roderick",
      "want": "娘ミーナと港町を守り、ヨハンの死後に自分が背負ってきた灯台の務めを失わずにいたい。",
      "need": "沈黙と過保護で娘を遠ざけるのをやめ、知っていることと知らないことを認めて、彼女自身の判断を信じる必要がある。",
      "fear": "自分の判断や教えが、ヨハンに続いてミーナまで危険にさらすこと。",
      "wound": "三年前、息子ヨハンを嵐の夜に失い、遺体も戻らないまま灯皿を大型化して九日分の油を確保した。",
      "secret": "灯皿を替えた理由と九日目の日没までの計算を抱え、鍵を失った後も松明の油で灯りを支えられるよう備えている。",
      "principle": "灯りを絶やさぬため、まず持ちこたえる時間を稼ぐ。ただし、娘を守ろうとするあまり、答えを伏せてしまう。",
      "self_view": "失った息子の分まで灯台を守る、務めを知る父親。",
      "others_view": [
        "ミーナから見れば、必要なことを黙り込み、危険を一人で引き受けようとする父。",
        "セスから見れば、油と松明の残りを計算して灯りをつなぐ灯台守。",
        "灯寮から見れば、教義を守る老練な守人。"
      ],
      "predictions": [
        {
          "situation": "嵐が迫り、鍵の三つ目の刻みを問われたとき。",
          "choice": "それを壊れていると教え、嵐の夜は鍵を手放すなと念を押す。"
        },
        {
          "situation": "ミーナがヨハンや雷のことを尋ねたとき。",
          "choice": "咳き込んで話を切り上げ、灯寮の名が出れば黙る。"
        },
        {
          "situation": "鍵を失い、灯りを九日目まで保つ必要があるとき。",
          "choice": "灯皿と松明の油を使って時間を稼ぎ、ミーナの判断を支える。"
        }
      ],
      "speech": {
        "sample": "油は九日目の日没までだ。鍵は嵐の夜に手放すな。それ以上を今ここで話すことはできん。",
        "vocab": [
          "油",
          "日没",
          "鍵",
          "務め"
        ],
        "avoid": [
          "大丈夫だ、何も起きない",
          "好きにしろ",
          "ヨハンは臆病者だ"
        ]
      },
      "arc": {
        "endpoint": "全てを黙って抱え込む父から、娘の選択を支え、灯台を共に守る父へ。",
        "changed": [
          "ミーナを危険から遠ざけるため何も語らない姿勢を改め、彼女の選択を認める。",
          "灯寮の教えだけを疑わぬ態度を崩し、娘が選ぶ半灯を支える。"
        ],
        "unchanged": [
          "油の残量と日没を計り、灯りをつなぐために手を尽くす。",
          "娘と港町を守ろうとする。"
        ]
      },
      "bans": [
        "ヨハンの遺体が戻ったと断言する。",
        "半灯の真実を初めから知っていたと振る舞う。",
        "油の九日分の備えを無意味なものとして扱う。"
      ]
    },
    {
      "id": "seth",
      "want": "使いとしての信頼を失わず、自分が拾った潮札を必要とする人へ届けたい。",
      "need": "読めないものを分かったふりせず、託すべき相手に託した後は、その人の判断を尊重する必要がある。",
      "fear": "自分が運んだものが誤解され、誰かを危険にさらすこと。",
      "wound": "三年前の嵐の後、浜で潮札を拾ったが、文字を読めず、長くその意味を確かめられなかった。",
      "secret": "文字のかすれた潮札を手元に保管し、内容を読めないまま灯台まで持ってきた。",
      "principle": "伝令の役目は、分からぬものを勝手に解釈することではなく、確かなまま届けること。",
      "self_view": "潮札を運ぶ使いであり、記された中身を決めつける者ではない。",
      "others_view": [
        "ミーナから見れば、兄の潮札を託してくれた協力者。",
        "ロデリクから見れば、灯りの現状を知る伝令。",
        "灯寮から見れば、潮札を運び、潮鏡の読み取りを助ける使い。"
      ],
      "predictions": [
        {
          "situation": "浜で拾った潮札の文字を読めないまま灯台へ来たとき。",
          "choice": "内容を推測で補わず、札をミーナに託す。"
        },
        {
          "situation": "潮鏡に鍵の所在が映っても、人や文字までは映らないと分かっているとき。",
          "choice": "映った範囲だけを伝え、見えないことを見えたとは言わない。"
        },
        {
          "situation": "ミーナが潮札を読むため血を落とすと決めたとき。",
          "choice": "使いとして必要な助けをしつつ、彼女に代わって決断しない。"
        }
      ],
      "speech": {
        "sample": "浜で拾った札だ。読めなかったから、書いてあることを勝手に決めず、そのまま持ってきた。",
        "vocab": [
          "届ける",
          "拾った",
          "潮札",
          "確かではない"
        ],
        "avoid": [
          "きっとこうだ",
          "たいしたことではない",
          "命令だから考えるな"
        ]
      },
      "arc": {
        "endpoint": "ただ札を運ぶだけの使いから、確かさを保って託し、受け取った者の選択を支える使いへ。",
        "changed": [
          "届けたら役目は終わりという考えから、真実を確かめる過程にも寄り添う。",
          "自分に読めない札を価値の分からない品として扱わず、必要な相手に託す。"
        ],
        "unchanged": [
          "見たことと推測を区別して伝える。",
          "潮札を勝手に書き換えたり、内容を捏造したりしない。"
        ]
      },
      "bans": [
        "潮札を読めたふりをする。",
        "潮鏡に人の姿や文字が映ると主張する。",
        "灯台と王都の移動日数を都合よく短縮する。"
      ]
    },
    {
      "id": "johan",
      "want": "港町の人々を、灯りに引き寄せられる沖の雷から守りたい。",
      "need": "一人で危険を引き受けるのではなく、灯りには霧を退ける以外の働きもあると生きている者に伝える必要があった。",
      "fear": "灯りが沖の雷を呼び、港町を焼くこと。",
      "wound": "灯寮が雷の事実を記録から削り、灯りを消した彼を臆病者の失敗として扱った。",
      "secret": "灯寮が否定する半灯の刻みと還り鍵の理を解く条件を潮札に記した。",
      "principle": "教えに反してでも、目の前の人々を現実の危険から守る。",
      "self_view": "灯守見習いとして、灯りの効能と害の双方を引き受ける者。",
      "others_view": [
        "ミーナから見れば、記録では罪を負わされたが、人々を守ろうとした兄。",
        "ロデリクから見れば、三年前の嵐に帰らなかった息子。",
        "灯寮の正史から見れば、霧を恐れて灯りを消した臆病者。"
      ],
      "predictions": [
        {
          "situation": "全灯が沖の雷を港町へ招くと知ったとき。",
          "choice": "灯寮の教えに反して灯りを消し、雷から港町を守ろうとする。"
        },
        {
          "situation": "半灯の手順と還り鍵の理を理解したとき。",
          "choice": "後に読む者の手がかりとなるよう、合わせ方と条件を潮札に残す。"
        },
        {
          "situation": "自分の選択が正史に記されず、誤解されると予測できたとき。",
          "choice": "危険を避ける選択を優先し、潮札に真実を託す。"
        }
      ],
      "speech": {
        "sample": "灯りは霧を退ける。けれど雷も呼ぶ。守るために消す夜があることを、誰かに伝えなくてはならない。",
        "vocab": [
          "守る",
          "雷",
          "霧",
          "伝える"
        ],
        "avoid": [
          "臆病者",
          "教えに従えば必ず安全だ",
          "何も残さなくていい"
        ]
      },
      "arc": {
        "endpoint": "死後、本人が語ることはない。潮札とミーナの選択を通じて、記録の罪人から、港町を守ろうとした灯守として真実が受け継がれる。",
        "changed": [
          "人物自身の現在の選択はない。残された潮札が、灯りを消すか守るかという問いを、半灯を選ぶ道へ導く。"
        ],
        "unchanged": [
          "教義よりも港町の人々を守る判断を優先した。",
          "自ら知った半灯と還り鍵の条件を潮札に記した。"
        ]
      },
      "bans": [
        "現在時の人物として登場したり、発話したりする。",
        "死後に石膏手形を動かす。",
        "潮札に書かれていない事実を、死後に新たに伝える。"
      ]
    },
    {
      "id": "hilda",
      "want": "灯寮の書記として記録を保ちながら、ヨハンの真実を隠蔽から守りたい。",
      "need": "記録を見つけるだけで満足せず、真実を知る者が判断できる形で伝える責任を引き受ける必要がある。",
      "fear": "真実を語れば灯寮に握りつぶされ、語らなければヨハンの選択が永遠に歪められること。",
      "wound": "正史から雷の記録が削られ、ヨハンの死が臆病者の失敗とされた痕跡を、王都の記録庫で見つけた。",
      "secret": "帰らぬ者の棚の手形札と削除前の草稿を突き合わせ、灯寮が隠した真実を知り、私的な覚え書きを残している。",
      "principle": "記録は権力の言い分ではなく、何が起きたかを後の者が確かめるためにある。",
      "self_view": "書記として証拠を守り、断定できることだけを伝える者。",
      "others_view": [
        "ミーナから見れば、兄の選択の真相と半灯の手順を明かす書記。",
        "灯寮から見れば、記録を管理する王都の書記。",
        "ヨハンの残したものから見れば、削除された事実を読み取った後世の証人。"
      ],
      "predictions": [
        {
          "situation": "帰らぬ者の棚で手形札と削除前の草稿を見つけたとき。",
          "choice": "記録を突き合わせ、ヨハンが雷から港町を守ろうとした証拠を確かめる。"
        },
        {
          "situation": "半灯の手順と還り鍵を解く覚え書きをミーナへ託すとき。",
          "choice": "手順を伝え、嵐の夜は鍵を握ったままとする条件も省かず記す。"
        },
        {
          "situation": "灯寮の公式記録に反する真実を語る危険があるとき。",
          "choice": "証拠に基づく範囲で伝え、ミーナ自身が選べるようにする。"
        }
      ],
      "speech": {
        "sample": "棚札の記録と削除前の草稿は一致していません。確かめられたことだけを、あなたに渡します。",
        "vocab": [
          "記録",
          "草稿",
          "確かめる",
          "証拠"
        ],
        "avoid": [
          "噂にすぎない",
          "記録にないから嘘だ",
          "黙って従いなさい"
        ]
      },
      "arc": {
        "endpoint": "記録を守るだけの書記から、証拠を伝え、灯寮の沈黙に抗う証人へ。",
        "changed": [
          "公的な記録の外にあるものを価値のないものとして扱わず、削除前の草稿と潮札も証拠として伝える。",
          "自分だけが真実を抱えず、ミーナが選べるように必要な手順を託す。"
        ],
        "unchanged": [
          "証拠を確認し、確かなことと不確かなことを分ける。",
          "ヨハンの真実を捏造せず、記録に基づいて語る。"
        ]
      },
      "bans": [
        "潮鏡で札の文字や人の姿を読めたと主張する。",
        "半灯を第2章まで灯寮公認の刻みとして扱う。",
        "ヨハンを現在時の人物として登場・発話させる。"
      ]
    }
  ]
}
